<script>document.addEventListener('DOMContentLoaded',()=>{const button=document.getElementById('toggle-schedule-form'),form=document.querySelector('form[action*="tour-schedule"]');if(!button||!form)return;form.classList.add('hidden');button.addEventListener('click',()=>{const closed=form.classList.toggle('hidden');button.textContent=closed?'+ Add schedule':'− Close schedule';if(!closed)form.scrollIntoView({behavior:'smooth',block:'center'});});});</script>
<script>document.addEventListener('DOMContentLoaded',()=>{const form=document.querySelector('form[action*="tour-schedule"]');if(!form)return;[['starts_at','Time in'],['ends_at','Time out']].forEach(([name,label])=>{const input=form.querySelector(`[name="${name}"]`);if(!input||input.parentElement.classList.contains('time-field'))return;const wrapper=document.createElement('label');wrapper.className='time-field';const text=document.createElement('span');text.textContent=label;wrapper.appendChild(text);input.replaceWith(wrapper);wrapper.appendChild(input);});});</script>
<script>document.addEventListener('DOMContentLoaded',()=>{const form=document.querySelector('form[action*="resource-allocation"]');if(!form)return;const button=document.createElement('button');button.type='button';button.className='add-button mt-5';button.textContent='+ Add resource';form.parentElement.insertBefore(button,form);form.classList.add('hidden');button.addEventListener('click',()=>{const closed=form.classList.toggle('hidden');button.textContent=closed?'+ Add resource':'− Close resource';if(!closed)form.scrollIntoView({behavior:'smooth',block:'center'});});});</script>
<script>document.addEventListener('DOMContentLoaded',()=>{const button=document.getElementById('toggle-schedule-form'),form=document.querySelector('form[action*="tour-schedule"]');if(!button||!form)return;const card=form.parentElement,outer=button.parentElement;card.insertBefore(button,form);button.classList.add('mt-5','self-start');outer.remove();});</script>
